      plain: `A <b>${isR ? 'resistance' : 'support'}</b> is a price where the market has ${isR ? 'stopped rising' : 'stopped falling'} before. It is found from: <b>${esc(why)}</b>. The more it was touched, the more traders remember it.`,
      secs: [sec('Strength', scale([{ w: 1, label: '1', tone: 'bad' }, { w: 1, label: '2', tone: 'warn' }, { w: 1, label: '3', tone: 'ok' }, { w: 1, label: '4+', tone: 'ok' }], .5, 4.5, Math.max(.5, Math.min(4.5, s || .5)), () => String(s)) + p('One point per touch, one more if it is the 24h high or low, half a point for a round number.')),
        sec('How to use it', tbl([{ c: [isR ? 'Long' : 'Short', isR ? 'a target: take profit before it' : 'a target: take profit before it'] }, { c: [isR ? 'Short' : 'Long', 'an entry area: a limit order here with the stop just beyond'] }]))],
