    if (el.matches && el.matches('.cnode') && /^[A-Z]{3}\/[A-Z]{3}$/.test(title)) return card({ title: `${title} on the map`, chip: el.classList.contains('cur') ? 'the pair open in your chart' : el.classList.contains('held') ? 'a pair you hold' : 'a pair of the tree', tone: '', plain: esc(body) || 'One currency pair.', secs: [sec('How to read a node', tbl([{ c: ['Size', 'its volatility: bigger moves more'] }, { c: ['Colour', 'green: up over the last 4 hours, red: down'] }, { c: ['Gold ring', 'the pair open in your chart'] }, { c: ['Lines to it', 'its direct links; the more links, the more central it is'] }]))], use: 'Click the node to open this pair in your chart.' });
    if (/ · \d+ links?$/.test(title)) { const n = parseInt(title.split(' · ')[1]), P = title.split(' · ')[0]; return card({ title: `${P}: a hub`, chip: `${n} direct links`, tone: n >= 4 ? 'warn' : '', value: String(n), vlabel: 'Pairs directly linked to it', plain: esc(body) || 'A hub is a pair linked to many others: its moves ripple through the tree.', secs: [sec('Why it matters', p('A hub carries the common driver of its neighbours. A trade on a hub is a trade on that whole group; a news item on it moves several of your positions at once.'))], use: 'Click it to open the pair. Check how many of your positions sit next to it.' }); }
    if (title === 'ρ (correlation)') return card({ title: 'ρ (correlation)', chip: 'how two pairs move together', tone: '', plain: esc(body) || 'From −1 to +1.', secs: [rhoScale(0), sec('Reading it', tbl([{ c: ['+1', 'they always move together'] }, { c: ['0', 'no relation'] }, { c: ['−1', 'they always move opposite'] }, { c: ['|ρ| > 0.7', 'strong: treat as one position'] }]))], watch: 'Correlation is not cause. It tells you what happened together, not what will.', use: 'Check it before adding a second pair to a trade.' });
