  add('.brx-card .brx-hd', false, el => { const t = lbl(el); const D = { 'Key levels': ['Resistances above the price and supports below, mapped from 7 days of 1H swings, the 24h high and low and round numbers. Each has a strength from 1 to 4+ (the dots).', 'Use them for stops and targets, never for blind entries.'], 'Plan template': ['A starting plan built by rules: entry at a level, stop beyond it, target at the next level, with the risk worked out for your size. It is a template, not a signal.', 'Check it against the chart and load it into the ticket only if you agree with it.'], 'Indicators': ['The four readings the brief is built on, each with a scale and a marker: RSI, ATR against the week, position in the 24h range and the currency strength.', 'Use them as a checklist: none of them should surprise you when you enter.'] }[t]; return D ? card({ title: t, chip: '', tone: '', plain: D[0], use: D[1] }) : null; });
