  add('#constSide .ins > label', false, el => { const t = lbl(el), D = { 'Unusual links now': ['Links behaving out of character: their correlation now is far from their normal level.', 'Look for news behind them, or a pair that has moved alone.'], 'Hubs — pairs with the most links': ['The pairs directly linked to the most others. Their moves ripple through the tree.', 'Check how much of your book sits next to a hub.'], 'Tightest link': ['The two pairs that move most alike right now. Trading both in the same direction is one position, sized twice.', 'Count them as one when you add up your risk.'], 'Most independent pair': ['The pair furthest from everything else: its moves have the least to do with the rest. The best partner when you want real diversification.', 'Pick it when you need a second trade that does not duplicate the first.'], 'Your positions': ['The pairs you hold right now, marked on the map. Held pairs that sit next to each other carry the same risk.', 'Close or reduce one of two held neighbours if you want diversification.'], 'Your currency exposure': ['The currencies your open positions net into: for example long EUR/USD and long EUR/GBP are both long EUR. It adds up the real exposure per currency.', 'Keep any single currency below your risk limit.'] }[t.replace(/\s+·.*$/, '')] || (/^Return interval/.test(t) ? ['How the average strength of the links changes with the return interval (1, 5 and 15 minutes). If it rises with the interval, part of the 1-minute correlation was noise.', 'Trust the links that hold on all three intervals.'] : null); return D ? card({ title: t, chip: 'a block of the side panel', tone: '', plain: D[0], use: D[1] }) : null; });
  add('#constSide .ins > p', false, el => card({ title: 'Your positions', chip: lbl(el).slice(0, 50), tone: '', plain: esc(lbl(el)), secs: [sec('Why it is here', p('The map is most useful when you hold something: held pairs get a ring, and the exposure per currency is added up. With nothing open there is nothing to show.'))], use: 'Open a trade, then come back: see whether your positions are neighbours.' }));
  add('.obs-ctrl > .muted.small', false, el => card({ title: 'Return interval', chip: 'the label of the 1m / 5m / 15m buttons', tone: '', plain: 'A <b>return</b> is the price change over a fixed interval. The matrix of correlations is computed on these returns: the buttons to the right choose the interval.', secs: [sec('Why the interval matters', p('Over 1 minute, the spread and the order flow add noise; over 15 minutes the slower, more economic links show. A link that exists at all intervals is a real one.'))], use: 'Switch the interval and watch which lines stay: those are the links worth using.' }));
  add('#constSide .obs-hero', false, el => { const r = parseFloat(U((lbl(el).match(/ρ\s*([+−-]?[\d.]+)/) || [])[1] || '')), names = (lbl(el).match(/[A-Z]{3}\/[A-Z]{3}/g) || []).join(' and '); return card({ title: 'Tightest link', chip: 'the two pairs that move most alike', tone: 'warn', value: isFinite(r) ? `ρ ${r.toFixed(2)}` : '—', vlabel: names || 'The strongest link in the tree', plain: 'These two pairs have the highest correlation of the whole tree now. In practice they are <b>one market seen twice</b>: if one gains, the other almost always does.', secs: [isFinite(r) ? rhoScale(r) : '', sec('What to do with it', tbl([{ c: ['Hold both, same direction', 'one position counted twice'] }, { c: ['Hold both, opposite direction', 'a near-hedge: they cancel'] }, { c: ['Need two trades', 'pick the Most independent pair below instead'] }]))], use: 'Add the lots of both pairs when you count your risk on this theme.' }); });
