  add('#rgCv', false, () => card({ title: 'The regime plot', chip: 'every pair placed by memory and randomness', tone: '', plain: 'Each dot is a pair. Its <b>horizontal</b> position is the Hurst exponent (persistent to the right, anti-persistent to the left), its <b>vertical</b> position the permutation entropy (more random upward). The grey band is where random paths of the same returns would fall.', secs: [sec('How to read it', tbl([{ c: ['Dot inside the band', 'indistinguishable from noise: most pairs, most of the time'] }, { c: ['Dot right of the band', 'trending recently'] }, { c: ['Dot left of the band', 'mean-reverting recently'] }, { c: ['Dot below the band', 'unusually ordered moves'] }, { c: ['Big dot', 'a volatile pair'] }]))], watch: 'A dot outside the band describes the recent path. It does not predict the next move.', use: 'Click a dot to open its pair; then read the side panel for the numbers.' }));
