  add('#rgSide .ins > label', false, el => { const t = lbl(el); if (/right now$/.test(t)) return card({ title: t, chip: 'the pair open in your chart', tone: '', plain: 'The regime of the pair you are looking at: its Hurst exponent, how far it is from the noise band, how long it has been in its zone, and how it changed over the last 12 hours.', use: 'Change the pair on the main chart, or click a dot, to see another.' }); if (/^Largest deviations/.test(t)) return card({ title: t, chip: 'the pairs furthest from noise', tone: '', plain: 'The pairs whose path is the least like random: the biggest gap to the noise band, in entropy or in Hurst. The count says how many of the 16 are still inside the band.', secs: [sec('How they are ranked', p('Each pair gets the larger of its two gaps (entropy and Hurst), in units of the band. The top ones are listed.'))], use: 'Click one to open it: look at the chart for the pattern behind the number.' }); if (/^Reading it honestly/.test(t)) return card({ title: t, chip: 'what the numbers do not say', tone: '', plain: 'A short reminder: a point outside the band describes how the pair has just moved. It is not a signal and it does not predict the next move.', use: 'Use the regime to choose which kind of strategy to trust, not to enter a trade.' }); return null; });
  add('#rgSide .ins > p:not(.rg-per)', false, el => regimeCard(pairOf(lbl(document.querySelector('#rgSide .ins > label') || el)) || 'The pair', lbl(el)) || textCard(el));
