  add('.rg-sort', true, el => { const D = { pair: ['Pair', 'Sorts the table by the name of the pair, in alphabetical order.'], H: ['H', 'Sorts by the Hurst exponent: the pairs with the most persistent or the most anti-persistent path come to the ends.'], pe: ['PE', 'Sorts by the permutation entropy: the pairs with the most ordered moves come first.'], er: ['ER', 'Sorts by the efficiency ratio: the pairs that made the most net progress come first.'], zone: ['Zone', 'Groups the pairs by zone: anti-persistent, noise, persistent.'], 'in': ['In zone', 'Sorts by how long each pair has been in its zone.'] }[el.dataset.k] || [lbl(el), 'Sorts the table by this column.']; return card({ title: `Sort by ${D[0]}`, chip: 'a table sort', tone: '', plain: D[1], use: 'Click again to reverse the order.' }); });
